with app.app_context():
    print("Starting restoration of Web Exploitations perfect state...")
    
    # 1. Restore challenges
    ctfd_whale_models = importlib.import_module("CTFd.plugins.ctfd-whale.models")
    DynamicDockerChallenge = ctfd_whale_models.DynamicDockerChallenge
    
    for c_info in exported_data["challenges"]:
        cid = c_info["id"]
        existing = Challenges.query.get(cid)
        if existing:
            db.session.delete(existing)
            db.session.commit()
            print(f"Deleted existing challenge ID {cid} for recreation")
            
        if c_info["is_dynamic"]:
            c = DynamicDockerChallenge(
                id=cid,
                name=c_info["name"],
                description=c_info["description"],
                category=c_info["category"],
                type=c_info["type"],
                state=c_info["state"],
                value=c_info["value"],
                initial=c_info["initial"],
                decay=c_info["decay"],
                minimum=c_info["minimum"],
                docker_image=c_info["docker_image"],
                redirect_type=c_info["redirect_type"],
                redirect_port=c_info["redirect_port"],
                memory_limit=c_info["memory_limit"],
                cpu_limit=c_info["cpu_limit"],
                dynamic_score=c_info["dynamic_score"]
            )
        else:
            c = Challenges(
                id=cid,
                name=c_info["name"],
                description=c_info["description"],
                category=c_info["category"],
                type=c_info["type"],
                state=c_info["state"],
                value=c_info["value"]
            )
            
        db.session.add(c)
        db.session.commit()
        print(f"Restored Challenge {cid}: {c.name} ({c.type})")
        
        if c_info["flag"]:
            Flags.query.filter_by(challenge_id=cid).delete()
            db.session.commit()
            
            flag_obj = Flags(
                challenge_id=cid,
                type="static",
                content=c_info["flag"],
                data=""
            )
            db.session.add(flag_obj)
            db.session.commit()
            print(f"Restored flag for Challenge {cid}")
            
    # 2. Restore lessons
    for lid_str, blocks in exported_data["lessons"].items():
        lid = int(lid_str)
        l = TutorialLesson.query.get(lid)
        if l:
            l.content = json.dumps(blocks, ensure_ascii=False)
            db.session.commit()
            print(f"Restored Lesson {lid} content successfully!")
            
    print("Database restoration complete! Hard refresh (Ctrl+F5) in the browser to see the base state.")
